                      if 0<=y+dy<H and 0<=x+dx<W and g[y+dy][x+dx]==col]
                rs=[p[0] for p in pcs]; cs=[p[1] for p in pcs]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # crop to nonzero core
                core_rows=[i for i in range(r0,r1+1) if any(p[0]==i for p in pcs)]
                core_cols=[j for j in range(c0,c1+1) if any(p[1]==j for p in pcs)]
                cr,cc=len(core_rows),len(core_cols)
                T=[[g[r0+i][c0+j] for j in core_cols] for i in core_rows]
                th,tw=cr,cc
                # anchor search: fill comp cells with T[(y-a)%th][(x-b)%tw]; try all a,b; prefer a=r0-? ; record best match
