                    return sc,bad
                best=None
                for a in range(th):
                    for b in range(tw):
                        s,bd=score(a,b,mode)
                        if best is None or (bd<s[1] if False else bd< (best[1] if best else 999)):
                            best=(a,b,s,bd)
